// One-hot state encoding
// State 0: Searching for the start of the sequence (1101)
// State 1: Found the start of the sequence; stay in this state
// forever, outputting start_shifting = 1.
// State 2: Found the sequence 1101; go back to State 0 to search for
// the next sequence.
typedef enum logic [1:0] {
    STATE_0 = 2'b00,
    STATE_1 = 2'b01,
    STATE_2 = 2'b10
} state_t;

module TopModule(
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);
    state_t state, next_state;
    logic [2:0] shift_reg;
    logic seq_found;

    // Sequential logic: register the current state and the input data
    // in a shift register, and the output of the FSM.
    always_ff @(posedge clk) begin
        state <= next_state;
        shift_reg <= {shift_reg[1:0], data};
        start_shifting <= (state == STATE_1);
    end

    // Combinational logic: determine the next state and whether a
    // sequence of 1101 has been found.
    always_comb begin
        next_state = state;
        seq_found = 0;
        case (state)
            STATE_0: begin
                if (shift_reg == 3'b110) next_state = STATE_1;
            end
            STATE_1: begin
                if (shift_reg == 3'b101) seq_found = 1;
            end
            STATE_2: begin
                if (shift_reg == 3'b110) next_state = STATE_1;
            end
        endcase
    end

    // Move to the next state at the end of the clock cycle.
    always_ff @(posedge clk) begin
        if (reset) state <= STATE_0;
        else if (seq_found) state <= STATE_2;
    end
endmodule

